
const $=(s,r=document)=>r.querySelector(s),$$=(s,r=document)=>[...r.querySelectorAll(s)];
const API='';let token=localStorage.getItem('fenix_token')||'';let me=null,chats=[],selected=null,messages=[],users=[],dark=localStorage.getItem('theme')==='dark',ws=null,replyId=null,editingId=null;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
async function api(path,opt={}){let h={'Content-Type':'application/json',...(opt.headers||{})};if(token)h.Authorization='Bearer '+token;let r=await fetch(API+path,{...opt,headers:h});let d;try{d=await r.json()}catch{d={detail:'Ошибка сервера'}}if(!r.ok)throw new Error(d.detail||'Ошибка');return d}
async function upload(file,kind='file'){let f=new FormData();f.append('file',file);let r=await fetch(API+(kind==='avatar'?'/api/files/avatar':'/api/files/upload'),{method:'POST',headers:token?{Authorization:'Bearer '+token}:{},body:f});let d=await r.json();if(!r.ok)throw new Error(d.detail||'Ошибка загрузки');return d}
function avatar(u,size=''){let name=esc(u?.display_name||u?.title||u?.username||'?');let letter=name.trim()[0]||'?';return `<div class="avatar ${size}">${u?.avatar?`<img src="${esc(u.avatar)}">`:letter}${u?.online?'<i class="dot"></i>':''}</div>`}
function auth(){document.body.className=dark?'dark':'';$('#app').innerHTML=`<div class="auth"><div class="authcard"><div class="authlogo">✈</div><h1>Fenix Messenger</h1><p>Быстрый и удобный мессенджер</p><div id="autherror" class="error hidden"></div><form class="form" id="authform"><input name="username" placeholder="Юзернейм (от 5 символов)" minlength="5" required><input name="display_name" placeholder="Имя" class="regfield hidden"><input name="password" type="password" placeholder="Пароль" minlength="6" required><button class="primary">Войти</button></form><button id="authswitch" class="secondary" style="width:100%;margin-top:10px">Создать аккаунт</button></div></div>`;let reg=false;$('#authswitch').onclick=()=>{reg=!reg;$('.regfield').classList.toggle('hidden',!reg);$('#authswitch').textContent=reg?'У меня уже есть аккаунт':'Создать аккаунт';$('#authform button').textContent=reg?'Зарегистрироваться':'Войти'};$('#authform').onsubmit=async e=>{e.preventDefault();let f=new FormData(e.currentTarget);let body={username:f.get('username'),password:f.get('password')};if(reg)body.display_name=f.get('display_name')||f.get('username');try{let d=await api(reg?'/api/auth/register':'/api/auth/login',{method:'POST',body:JSON.stringify(body)});token=d.access_token;localStorage.setItem('fenix_token',token);await boot()}catch(x){$('#autherror').textContent=x.message;$('#autherror').classList.remove('hidden')}}}
async function boot(){try{me=await api('/api/auth/me');await loadChats();render()}catch(e){localStorage.removeItem('fenix_token');token='';auth()}}
async function loadChats(){chats=await api('/api/chats');let saved=await api('/api/chats/saved').catch(()=>null);if(saved&&!chats.some(c=>c.id===saved.id))chats.unshift(saved);users=await api('/api/users').catch(()=>[])}
function render(){document.body.className=dark?'dark':'';$('#app').innerHTML=`<div class="app ${selected?'chat-open':''}" id="root"><aside class="sidebar"><div class="topbar"><button class="icon" id="menu">☰</button><div class="brand">Fenix</div><button class="icon" id="newchat">✎</button></div><div class="search"><span>⌕</span><input id="globalq" placeholder="Поиск"></div><div class="folders"><button class="on" data-folder="all">Все</button><button data-folder="unread">Непрочитанные</button><button data-folder="groups">Группы</button><button data-folder="channels">Каналы</button><button data-folder="saved">Избранное</button></div><div class="chatlist" id="chatlist"></div><div class="topbar" style="border-top:1px solid var(--line)"><button class="icon" id="profile">${avatar(me,'')}</button><button class="icon" id="theme">${dark?'☀':'☾'}</button><button class="icon" id="settings">⚙</button></div></aside><main class="chatmain"><div id="chathead"></div><div id="messages" class="messages"></div><div id="composer"></div></main><div id="overlay"></div></div>`;bindBase();drawChats();drawChat()}
function bindBase(){$('#menu').onclick=()=>showMenu();$('#newchat').onclick=()=>newChat();$('#profile').onclick=()=>profilePanel();$('#theme').onclick=()=>{dark=!dark;localStorage.setItem('theme',dark?'dark':'light');render()};$('#settings').onclick=()=>settingsPanel();$('#globalq').oninput=e=>drawChats(e.target.value);$$('.folders button').forEach(b=>b.onclick=()=>{ $$('.folders button').forEach(x=>x.classList.remove('on'));b.classList.add('on');drawChats($('#globalq').value,b.dataset.folder)})}
function drawChats(q='',folder='all'){let a=chats.filter(c=>{if(folder==='groups')return c.kind==='group';if(folder==='channels')return c.kind==='channel';if(folder==='saved')return c.kind==='saved';return true}).filter(c=>(c.title||'').toLowerCase().includes(q.toLowerCase()));$('#chatlist').innerHTML=a.length?a.map(c=>`<button class="chat ${selected?.id===c.id?'on':''}" data-id="${c.id}">${avatar(c)}<div style="min-width:0;flex:1"><div style="display:flex;justify-content:space-between"><b>${esc(c.title)}</b><span class="time muted">${c.kind==='private'?'':c.kind==='group'?'группа':' '}</span></div><div class="preview muted">${esc(c.description||'Начать общение')}</div></div></button>`).join(''):`<div class="empty">Нет чатов</div>`;$$('.chat').forEach(x=>x.onclick=()=>openChat(+x.dataset.id))}
async function openChat(id){selected=chats.find(c=>c.id===id);replyId=null;editingId=null;await loadMessages();render()}
async function loadMessages(){messages=selected?await api(`/api/chats/${selected.id}/messages`):[]}
function drawChat(){if(!selected){$('#chathead').innerHTML=`<div class="empty"><div><strong>Fenix Messenger</strong><br><span>Выберите чат, чтобы начать общение</span></div></div>`;$('#messages').innerHTML='';$('#composer').innerHTML='';return}$('#chathead').innerHTML=`<header class="head"><button class="icon mobile-only" id="back">‹</button>${avatar(selected)}<div class="headinfo"><div class="title">${esc(selected.title)}</div><div class="sub">${selected.kind==='private'?'в сети':'участники'}</div></div><button class="icon" id="chatsearch">⌕</button><button class="icon" id="chatmenu">⋮</button></header>`;$('#back').onclick=()=>{selected=null;render()};$('#chatsearch').onclick=()=>searchInChat();$('#chatmenu').onclick=()=>chatMenu();$('#messages').innerHTML=`<div class="day">Сегодня</div>`+messages.map(messageHTML).join('');bindMessageActions();$('#composer').innerHTML=`<div class="composer"><button class="icon" id="attach">📎</button><button class="icon" id="emoji">☺</button><input id="msginput" placeholder="Сообщение" value="${editingId?'':''}"><button class="send" id="send">➤</button></div>`;$('#attach').onclick=attachMenu;$('#emoji').onclick=emojiPicker;$('#send').onclick=sendMessage;$('#msginput').onkeydown=e=>{if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();sendMessage()}};if(wsConnect)wsConnect()}
function messageHTML(m){let mine=m.sender_id===me.id;return `<div class="msg ${mine?'mine':''}" data-mid="${m.id}"><div class="bubble">${m.reply_to_id?`<div class="reply">Ответ на сообщение #${m.reply_to_id}</div>`:''}${!mine&&selected.kind!=='saved'?`<div class="sender">Пользователь ${m.sender_id}</div>`:''}${m.media_url?`<a href="${esc(m.media_url)}" target="_blank">📎 ${esc(m.media_type||'файл')}</a>`:''}${m.deleted?'<i>Сообщение удалено</i>':`<span class="text">${esc(m.text)}</span>`}<span class="meta">${new Date(m.created_at).toLocaleTimeString([], {hour:'2-digit',minute:'2-digit'})} ${m.edited?'изменено ':''}${mine?'<span class="checks">✓✓</span>':''}</span><div class="menu-list hidden msgmenu"><button data-act="reply">↩ Ответить</button><button data-act="copy">▣ Копировать</button><button data-act="pin">📌 Закрепить</button>${mine?'<button data-act="edit">✎ Изменить</button><button data-act="delete" class="danger">Удалить</button>':''}<button data-act="react">❤️ Реакция</button></div></div></div>`}
function bindMessageActions(){$$('.bubble').forEach(b=>b.onclick=e=>{if(e.target.closest('.msgmenu'))return;$$('.msgmenu').forEach(x=>x.classList.add('hidden'));$('.msgmenu',b).classList.remove('hidden')});$$('.msgmenu button').forEach(x=>x.onclick=async e=>{let act=x.dataset.act,id=+x.closest('.msg').dataset.mid; if(act==='reply'){replyId=id;$('#msginput').focus()}if(act==='copy'){let m=messages.find(z=>z.id===id);navigator.clipboard?.writeText(m?.text||'')}if(act==='delete'){await api(`/api/chats/${selected.id}/messages/${id}`,{method:'DELETE'});await loadMessages();drawChat()}if(act==='edit'){let m=messages.find(z=>z.id===id);let input=$('#msginput');input.value=m.text;editingId=id;input.focus()}if(act==='pin'){await api(`/api/chats/${selected.id}/messages/${id}/pin`,{method:'POST'});await loadMessages();drawChat()}if(act==='react'){await api(`/api/chats/${selected.id}/messages/${id}/reaction`,{method:'POST',body:JSON.stringify({emoji:'❤️'})})};e.stopPropagation()})}
async function sendMessage(){let i=$('#msginput'),text=i.value.trim();if(!text)return;try{if(editingId){await api(`/api/chats/${selected.id}/messages/${editingId}`,{method:'PATCH',body:JSON.stringify({text})});editingId=null}else await api(`/api/chats/${selected.id}/messages`,{method:'POST',body:JSON.stringify({text,reply_to_id:replyId})});i.value='';replyId=null;await loadMessages();drawChat()}catch(e){alert(e.message)}}
function attachMenu(){let box=document.createElement('div');box.className='menu-list';box.innerHTML='<button>📷 Фото / видео</button><button>📎 Документ</button><button>🎵 Аудио</button><button>🎤 Голосовое</button>';box.style.bottom='65px';box.style.left='12px';$('#composer').append(box);box.firstChild.onclick=()=>pickFile(true);box.children[1].onclick=()=>pickFile(false)}
function pickFile(image){let f=document.createElement('input');f.type='file';f.accept=image?'image/*':'*/*';f.onchange=async()=>{try{let d=await upload(f.files[0]);await api(`/api/chats/${selected.id}/messages`,{method:'POST',body:JSON.stringify({text:d.name,media_url:d.url,media_type:d.content_type})});await loadMessages();drawChat()}catch(e){alert(e.message)}};f.click()}
function emojiPicker(){let p=document.createElement('div');p.className='picker';let em='😀 😃 😄 😁 😆 😅 😂 🤣 😊 😇 🙂 🙃 😉 😌 😍 🥰 😘 😎 🤩 🤔 😐 😑 😶 🙄 😏 😣 😥 😮 🤐 😯 😪 😫 🥱 😴 🤗 🤭 🤫 🤥 😶‍🌫️ 😱 😭 😤 😡 🤬 🤯 😳 🥳 ❤️ 🧡 💛 💚 💙 💜 🖤 🤍 💔 💯 🔥 👍 👎 👋 🙏 👏 🎉 ✨'.split(' ');p.innerHTML='<div class="emoji-grid">'+em.map(x=>`<button>${x}</button>`).join('')+'</div>';$('#composer').append(p);$$('.emoji-grid button',p).forEach(b=>b.onclick=()=>{$('#msginput').value+=b.textContent;$('#msginput').focus();p.remove()})}
function showMenu(){overlay(`<div class="modal"><h2>Меню</h2><div class="row"><div class="grow"><b>${esc(me.display_name)}</b><small>@${esc(me.username)} · ID ${me.public_code||me.id}</small></div></div><button class="secondary" style="width:100%;margin-top:10px" onclick="profilePanel()">👤 Профиль</button><button class="secondary" style="width:100%;margin-top:8px" onclick="settingsPanel()">⚙ Настройки</button><button class="secondary" style="width:100%;margin-top:8px" onclick="newChat()">✎ Новое сообщение</button><button class="secondary" style="width:100%;margin-top:8px" onclick="logout()">🚪 Выйти</button></div>`)}
async function newChat(){await loadChats();overlay(`<div class="modal"><h2>Новое сообщение</h2><div class="search"><span>⌕</span><input id="userq" placeholder="Имя, @username или 3/4-значный ID"></div><div id="people">${users.map(u=>`<button class="row person" data-id="${u.id}">${avatar(u)}<div class="grow"><b>${esc(u.display_name)}</b><small>@${esc(u.username)} · ID ${u.public_code||u.id}</small></div></button>`).join('')}</div></div>`);$('#userq').oninput=e=>{$$('.person').forEach(p=>p.classList.toggle('hidden',!p.innerText.toLowerCase().includes(e.target.value.toLowerCase())))};$$('.person').forEach(p=>p.onclick=async()=>{let c=await api('/api/chats/private',{method:'POST',body:JSON.stringify({other_user_id:+p.dataset.id})});chats.unshift(c);closeOverlay();openChat(c.id)})}
function profilePanel(){overlay(`<div class="modal"><h2>Профиль</h2><div class="hero">${avatar(me)}<h2>${esc(me.display_name)}</h2><p>@${esc(me.username)} · ID ${me.public_code||me.id}</p></div><div class="form" style="margin-top:18px"><input id="pname" value="${esc(me.display_name)}" placeholder="Имя"><input id="pbio" value="${esc(me.bio||'')}" placeholder="О себе"><button class="primary" id="savep">Сохранить</button><button class="secondary" id="ava">Изменить аватар</button></div></div>`);$('#savep').onclick=async()=>{me=await api('/api/users/me',{method:'PATCH',body:JSON.stringify({display_name:$('#pname').value,bio:$('#pbio').value})});closeOverlay();render()};$('#ava').onclick=()=>{let f=document.createElement('input');f.type='file';f.accept='image/*';f.onchange=async()=>{await upload(f.files[0],'avatar');me=await api('/api/auth/me');closeOverlay();render()};f.click()}}
function settingsPanel(){overlay(`<div class="modal"><h2>Настройки</h2><div class="row"><span>🌙 Тёмная тема</span><button class="secondary" id="settheme">${dark?'Выкл':'Вкл'}</button></div><div class="row"><span>🔔 Уведомления</span><button class="secondary">Настроить</button></div><div class="row"><span>🔒 Приватность</span><button class="secondary">Открыть</button></div><div class="row"><span>📱 Активные сессии</span><button class="secondary">Устройства</button></div></div>`);$('#settheme').onclick=()=>{dark=!dark;localStorage.setItem('theme',dark?'dark':'light');closeOverlay();render()}}
function chatMenu(){overlay(`<div class="modal"><h2>${esc(selected.title)}</h2><button class="row">🔔 Уведомления <span class="grow"></span> Вкл</button><button class="row">📌 Закрепить чат</button><button class="row">🔎 Поиск в чате</button><button class="row">🖼 Медиа и файлы</button><button class="row danger">🚫 Заблокировать / покинуть</button></div>`)}
function searchInChat(){let q=prompt('Поиск в чате');if(!q)return;let hits=messages.filter(m=>m.text.toLowerCase().includes(q.toLowerCase()));alert(`Найдено: ${hits.length}`)}
function overlay(content){$('#overlay').innerHTML=`<div class="modalshade" id="shade"><div onclick="event.stopPropagation()">${content}</div></div>`;$('#shade').onclick=closeOverlay}function closeOverlay(){$('#overlay').innerHTML=''}
async function logout(){try{await api('/api/auth/logout',{method:'POST',body:'{}'})}catch{}localStorage.removeItem('fenix_token');token='';me=null;selected=null;auth()}
function wsConnect(){if(ws)try{ws.close()}catch{}if(!token||!selected)return;ws=new WebSocket(`${location.protocol==='https:'?'wss':'ws'}://${location.host}/ws/${selected.id}?token=${encodeURIComponent(token)}`);ws.onmessage=async e=>{let d=JSON.parse(e.data);if(d.type==='message'){messages.push(d.message);$('#messages').innerHTML='<div class="day">Сегодня</div>'+messages.map(messageHTML).join('');bindMessageActions();let el=$('#messages');el.scrollTop=el.scrollHeight}}}
if(token)boot();else auth();
